_CAUSAL_GAM_EQUATION: dict[str, Any] | None = None
_CAUSAL_GAM_DYNAMIC = (
    "monthly_precipitation", "dryness", "air_temperature", "gpp",
    "leaf_area_index", "lightning_flash_rate",
)


def _causal_process_gam(
    prediction: np.ndarray,
    data: Mapping[str, np.ndarray],
    p: Mapping[str, float],
    enabled: set[str],
) -> np.ndarray:
    """Apply a pointwise GAM over causal fuel, moisture and ignition state.

    Every one- and two-variable response is globally shared. Interactions with
    urban fraction were removed because they could turn sparse settlement into
    a geographic proxy; retained pairs couple only fire opportunity, climate
    memory, vegetation/fuel, ignition, management, depletion, and phenology.
    """
    strength = float(np.clip(p.get("causal_gam_w", 0.0), 0.0, 1.25))
    if "causal_gam" not in enabled or strength <= 0.0:
        return prediction

    global _CAUSAL_GAM_EQUATION
    if _CAUSAL_GAM_EQUATION is None:
        _CAUSAL_GAM_EQUATION = pickle.loads(
            zlib.decompress(base64.b85decode(_CAUSAL_GAM_B85))
        )
    equation = _CAUSAL_GAM_EQUATION
    bins = equation["bins"]
    terms = equation["terms"]

    base = np.asarray(prediction, dtype=np.float64)
    cumulative = np.cumsum(base, axis=0, dtype=np.float64)
    trailing = cumulative.copy()
    trailing[12:] -= cumulative[:-12]
    exposure = np.minimum(np.arange(1, base.shape[0] + 1), 12)[:, None, None]
    trailing *= 12.0 / exposure
    share = base / (trailing + 1e-12)
    land = (
        (np.asarray(data["annual_precipitation"])[0] > 0.0)
        | (np.abs(np.asarray(data["air_temperature"])[0]) > 1e-6)
        | (np.asarray(data["natural_vegetation_fraction"])[0] > 0.0)
        | (np.asarray(data["secondary_vegetation_fraction"])[0] > 0.0)
    )
    selected = np.flatnonzero(land.ravel())
    raw = {
        name: np.asarray(data[name], dtype=np.float64).reshape(
            base.shape[0], -1
        )[:, selected]
        for name in INPUTS
    }
    base_flat = base.reshape(base.shape[0], -1)
    trailing_flat = trailing.reshape(trailing.shape[0], -1)
    share_flat = share.reshape(share.shape[0], -1)

    memories = {
        name: {months: raw[name][0].copy() for months in (3.0, 12.0, 24.0)}
        for name in _CAUSAL_GAM_DYNAMIC
    }
    means = {name: np.zeros(selected.size) for name in _CAUSAL_GAM_DYNAMIC}
    m2 = {name: np.zeros(selected.size) for name in _CAUSAL_GAM_DYNAMIC}
    minima = {name: raw[name][0].copy() for name in _CAUSAL_GAM_DYNAMIC}
    maxima = {name: raw[name][0].copy() for name in _CAUSAL_GAM_DYNAMIC}
    calendar_means = {
        name: np.zeros((12, selected.size)) for name in _CAUSAL_GAM_DYNAMIC
    }
    calendar_counts = np.zeros(12, dtype=np.int64)
    corrected = base.copy().reshape(base.shape[0], -1)

    for time in range(base.shape[0]):
        names: list[str] = ["incumbent", "trailing_annual", "fire_share"]
        fields: list[np.ndarray] = [
            base_flat[time, selected],
            trailing_flat[time, selected],
            share_flat[time, selected],
        ]
        for name in INPUTS:
            names.append(f"{name}:current")
            fields.append(raw[name][time])
        for name in _CAUSAL_GAM_DYNAMIC:
            current = raw[name][time]
            for months in (3.0, 12.0, 24.0):
                state = memories[name][months]
                state += (1.0 - np.exp(-1.0 / months)) * (current - state)
                names.extend(
                    (f"{name}:memory_{months:g}m", f"{name}:departure_{months:g}m")
                )
                fields.extend(
                    (state, (current - state) / (np.abs(current) + np.abs(state) + 1e-3))
                )
        angle = 2.0 * np.pi * (time % 12) / 12.0
        for harmonic in (1, 2, 3):
            names.extend((f"sin_month_{harmonic}", f"cos_month_{harmonic}"))
            fields.extend(
                (
                    np.full(selected.size, np.sin(harmonic * angle)),
                    np.full(selected.size, np.cos(harmonic * angle)),
                )
            )

        calendar_counts[time % 12] += 1
        for name in _CAUSAL_GAM_DYNAMIC:
            current = raw[name][time]
            count = time + 1
            delta = current - means[name]
            means[name] += delta / count
            m2[name] += delta * (current - means[name])
            spread = np.sqrt(m2[name] / count)
            minima[name] = np.minimum(minima[name], current)
            maxima[name] = np.maximum(maxima[name], current)
            month_mean = calendar_means[name][time % 12]
            month_mean += (current - month_mean) / calendar_counts[time % 12]
            recent = raw[name][max(0, time - 11) : time + 1]
            previous_year = raw[name][time - 12] if time >= 12 else raw[name][0]
            names.extend(
                (
                    f"{name}:expanding_mean", f"{name}:expanding_std",
                    f"{name}:expanding_min", f"{name}:expanding_max",
                    f"{name}:trailing_12m_min", f"{name}:trailing_12m_max",
                    f"{name}:calendar_mean", f"{name}:calendar_departure",
                    f"{name}:previous_year",
                )
            )
            fields.extend(
                (
                    means[name], spread, minima[name], maxima[name],
                    recent.min(axis=0), recent.max(axis=0), month_mean,
                    current - month_mean, previous_year,
                )
            )

        by_name = dict(zip(names, fields, strict=True))
        gpp_background = by_name["gpp:expanding_mean"]
        fine_fuel = gpp_background / (gpp_background + 0.20)
        biomass = by_name["aboveground_biomass:current"]
        woody_fuel = biomass / (biomass + 1.0)
        fuel_continuity = 1.0 - (1.0 - fine_fuel) * (1.0 - woody_fuel)
        natural = by_name["natural_vegetation_fraction:current"]
        canopy = by_name["natural_canopy_height:current"]
        rangeland = by_name["luh2_rangeland_fraction:current"]
        cropland = by_name["luh2_cropland_fraction:current"]
        open_cover = np.clip(
            natural * 10.0 / (canopy + 10.0) + rangeland, 0.0, 1.0
        )
        open_fuel = fuel_continuity * open_cover
        rain_mean = by_name["monthly_precipitation:expanding_mean"]
        rain_std = by_name["monthly_precipitation:expanding_std"]
        seasonal_fuel_pump = open_fuel * rain_std / (
            rain_mean + rain_std + 25.0
        )
        current_gpp = by_name["gpp:current"]
        calendar_gpp = by_name["gpp:calendar_mean"]
        curing_state = np.maximum(
            (calendar_gpp - current_gpp)
            / (np.abs(calendar_gpp) + np.abs(current_gpp) + 0.20), 0.0
        )
        current_rain = by_name["monthly_precipitation:current"]
        calendar_rain = by_name["monthly_precipitation:calendar_mean"]
        rain_deficit = np.maximum(
            (calendar_rain - current_rain) / (calendar_rain + current_rain + 10.0),
            0.0,
        )
        dryness_state = by_name["dryness:current"]
        temperature_state = by_name["air_temperature:current"]
        combustion_window = (
            dryness_state / (dryness_state + 500.0)
            * rain_deficit
            * _rising(temperature_state, 1.0 / 3.0, 5.0)
        )
        lightning_background = by_name["lightning_flash_rate:calendar_mean"]
        lightning_chance = lightning_background / (lightning_background + 0.01)
        natural_ignition = open_fuel * combustion_window * lightning_chance
        managed_ignition = (
            np.clip(cropland + rangeland, 0.0, 1.0)
            * fine_fuel * combustion_window
        )
        temperature_background = by_name["air_temperature:expanding_mean"]
        cold_forest_ignition = (
            natural * canopy / (canopy + 8.0) * woody_fuel
            * _falling(temperature_background, 1.0 / 3.0, 8.0)
            * lightning_chance
        )
        leaf_area = by_name["leaf_area_index:current"]
        annual_rain = by_name["annual_precipitation:current"]
        closed_canopy_moisture = (
            natural * canopy / (canopy + 12.0)
            * leaf_area / (leaf_area + 2.5)
            * annual_rain / (annual_rain + 1200.0)
        )
        recent_fire = by_name["trailing_annual"]
        fire_return_gap = 1.0 / (1.0 + recent_fire / 0.04)
        recurrent_combustion = (
            recent_fire / (recent_fire + 0.04) * combustion_window
        )
        mechanism_names = (
            "mechanism:fuel_continuity", "mechanism:open_fuel_continuity",
            "mechanism:seasonal_fuel_pump", "mechanism:curing_state",
            "mechanism:rain_deficit", "mechanism:combustion_window",
            "mechanism:natural_ignition", "mechanism:managed_ignition",
            "mechanism:cold_forest_ignition", "mechanism:closed_canopy_moisture",
            "mechanism:fire_return_gap", "mechanism:recurrent_combustion",
        )
        mechanism_fields = (
            fuel_continuity, open_fuel, seasonal_fuel_pump, curing_state,
            rain_deficit, combustion_window, natural_ignition, managed_ignition,
            cold_forest_ignition, closed_canopy_moisture, fire_return_gap,
            recurrent_combustion,
        )
        names.extend(mechanism_names)
        fields.extend(mechanism_fields)
        if time == 0 and tuple(names) != equation["feature_names"]:
            raise RuntimeError("causal GAM feature order mismatch")

        values = np.column_stack(fields)
        log_factor = np.full(
            selected.size, float(equation["intercept"]), dtype=np.float64
        )
        for features, scores in terms:
            level = len(features) - 1
            indices = []
            for feature in features:
                feature_bins = bins[feature]
                cuts = feature_bins[min(level, len(feature_bins) - 1)]
                indices.append(
                    np.searchsorted(cuts, values[:, feature], side="right") + 1
                )
            log_factor += scores[tuple(indices)]
        factor = np.exp(np.clip(log_factor, -30.0, 30.0))
        corrected[time, selected] *= np.power(factor, strength)
    return np.asarray(
        np.clip(corrected.reshape(base.shape), 0.0, 1.0), dtype=np.float32
    )



def predict(
    data: Mapping[str, np.ndarray],
    params: Mapping[str, float] | None = None,
    components: Collection[str] | None = None,
) -> np.ndarray:
    fallback = dict(PARAMS)
    if params is not None:
        fallback.update(params)
    enabled = set(COMPONENTS if components is None else components)
    unknown = enabled - set(COMPONENTS)
    if unknown:
        raise ValueError(f"unknown model components: {sorted(unknown)}")

    # Build one globally shared pointwise fire-rate equation. Geographic boxes
    # and region-specific parameter sets are deliberately excluded: an ED site
    # must receive the same response for the same local ecological state.
    rate = _fire_rate(data, fallback, enabled)

    if "cropland" in enabled and fallback.get("crop_k", 0.0) > 0.0:
        # Cropland cells burn less than the surrounding landscape yet the
        # biophysical model overpredicts them: weighted against the residual,
        # cropland fraction correlates -0.27 with observed burning but +0.12
        # with the model's error. Fields are ploughed, grazed and cut by roads
        # and field boundaries, so fuel is removed before the fire season and
        # what remains cannot carry a front across the landscape.
        crop = np.clip(data["luh2_cropland_fraction"], 0.0, 1.0)
        p_ = fallback
        rate = rate * (1.0 / (1.0 + p_["crop_k"] * np.power(crop, p_["crop_n"])))
    if "vpd" in enabled:
        rate = rate * _vpd(data, fallback)
    if "curing" in enabled:
        rate = rate * _curing(data, fallback)
    if "lag" in enabled:
        rate = _lag(rate, fallback)
    if "stubble" in enabled and fallback.get("stub_k", 0.0) > 0.0:
        # Central Asia burns in April while every climate driver there peaks
        # in July to September, and dryness is at its annual minimum as fire
        # ramps. That season is stubble clearing, which follows a planting
        # calendar rather than the weather, and the three most agricultural
        # regions (0.34, 0.34, 0.38 cropland fraction) are exactly the three
        # with the worst phase errors. LUH2 carries no calendar of its own --
        # its fields are annual values repeated monthly -- but the shoulders
        # of the growing season are recoverable from temperature. Fire the
        # term as the land crosses a growth threshold, gated on how much
        # cropland is there to burn.
        temperature = data["air_temperature"]
        warming = temperature - np.roll(temperature, 1, axis=0)
        warming[0] = 0.0
        shoulder = np.exp(
            -np.square((temperature - fallback["stub_t"]) / fallback["stub_w"])
        )
        crop = np.clip(data["luh2_cropland_fraction"], 0.0, 1.0)
        rate = rate * (
            1.0 + fallback["stub_k"] * crop * shoulder * np.clip(warming, 0.0, None)
        )
    if "pasture" in enabled and fallback.get("past_k", 0.0) > 0.0:
        # Rangeland is managed by burning too, but for a different reason and
        # on a different schedule than crop stubble: graziers fire the sward
        # to kill woody seedlings and flush new growth, which is done in the
        # dry season when the grass is cured rather than at sowing. Gate on
        # rangeland fraction and fire on the warm dry end of the year, keeping
        # the calendar shape that made the cropland term work while giving it
        # its own timing.
        temperature = data["air_temperature"]
        window = np.exp(
            -np.square((temperature - fallback["past_t"]) / fallback["past_w"])
        )
        graze = np.clip(data["luh2_rangeland_fraction"], 0.0, 1.0)
        rate = rate * (1.0 + fallback["past_k"] * graze * window)
    if "neighbour" in enabled:
        rate = _neighbour(rate, fallback)
    if "spread" in enabled:
        rate = rate * _spread(rate, fallback)
    prediction = _transform(rate, fallback)
    if "gust" in enabled:
        prediction = _gust(prediction, data, fallback)
    # Set fire potential from a trailing annual window. Seasonal timing then
    # remains a causal function of current and accumulated local state.
    prediction = _coupled_annual_correction(prediction, data, fallback, enabled)
    prediction = _ecological_regime_brakes(prediction, data, fallback, enabled)
    prediction = np.clip(
        prediction * fallback.get("annual_scale", 1.0), 0.0, 1.0
    )
    prediction = _causal_memory_gam(prediction, data, fallback, enabled)
    prediction = _causal_mechanistic_glm(prediction, data, fallback, enabled)
    prediction = _absolute_causal_glm(prediction, data, fallback, enabled)
    prediction = _ecological_fire_capacity(prediction, data, fallback, enabled)
    prediction = _seasonal_rainfall_capacity(
        prediction, data, fallback, enabled
    )
    prediction = _state_dependent_fire_season(
        prediction, data, fallback, enabled
    )
    prediction = _rare_lightning_ignition(prediction, data, fallback, enabled)
    prediction = _live_fuel_greenup_brake(
        prediction, data, fallback, enabled
    )
    prediction = _causal_process_gam(prediction, data, fallback, enabled)
    return np.asarray(np.clip(prediction, 0.0, 1.0), dtype=np.float32)
